import {brushes,stamps,updateBrushSummary} from './brush-ui.js';
import {fitBoard,createFocusMode} from './viewport.js';
import {patterns,patternCategories,svgMarkup} from './patterns.js';
import {W,H,MAX_STROKES,MAX_POINTS,coordinate,drawStroke,validDocument,backgroundColor} from './engine.js';
const $=s=>document.querySelector(s),canvas=$('#ink'),ctx=canvas.getContext('2d'),KEY='little-color-garden-v1';
const palette=[['#ed7976','草莓紅'],['#f5aa62','橘子橙'],['#f3d36b','陽光黃'],['#8bbf83','嫩葉綠'],['#70b8b1','湖水綠'],['#7ba8d3','天空藍'],['#a89bcc','葡萄紫'],['#e3a0b8','櫻花粉'],['#9f7e69','可可棕'],['#42545b','石頭黑'],['#e83456','莓果紅'],['#ff7648','珊瑚橘'],['#ffe135','亮亮黃'],['#39a66d','森林綠'],['#26c6c1','薄荷青'],['#2583dc','海洋藍'],['#7455c6','魔法紫'],['#f16ec3','糖果粉'],['#754b36','巧克力'],['#ffffff','白色']];
let stampShape='star',rainbow=false;
let state={version:1,pattern:'blank',strokes:[]},redo=[],color=palette[0][0],tool='marker',size=20,active=null,pointer=null,frame=0,saving=0,confirmAction=null,exportUrl=null,restoreMessage='',saveFailed=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validDocument(parsed,patterns.map(p=>p.id)))state=parsed;else restoreMessage='舊暫存無法讀取；請另存喜歡的作品。'}}catch{restoreMessage='瀏覽器無法讀取暫存，離開前請儲存圖片。'}
let history=state.strokes.map(stroke=>({kind:'stroke',stroke}));
const committed=document.createElement('canvas');committed.width=W;committed.height=H;const committedCtx=committed.getContext('2d');let dirty=true;
function render(){frame=0;$('#board').style.background=backgroundColor(state);if(dirty){committedCtx.clearRect(0,0,W,H);for(const s of state.strokes)drawStroke(committedCtx,s);dirty=false}ctx.clearRect(0,0,W,H);ctx.drawImage(committed,0,0);if(active)drawStroke(ctx,active);$('#welcome').hidden=state.pattern!=='blank'||state.strokes.length>0||!!active;$('#welcome').style.display=$('#welcome').hidden?'none':'';$('#undo').disabled=!history.length;$('#focus-undo').disabled=!history.length;$('#redo').disabled=!redo.length}
function schedule(){if(!frame)frame=requestAnimationFrame(render)}
function save(){clearTimeout(saving);try{localStorage.setItem(KEY,JSON.stringify(state));saveFailed=false;$('#save-status').textContent='✓ 已暫存在這台裝置'}catch{saveFailed=true;$('#save-status').textContent='暫存空間不足，請大人儲存圖片。'}}
function changed(){dirty=true;render();saving=setTimeout(save,300)}
function finish(){if(pointer===null)return;const id=pointer;pointer=null;if(canvas.hasPointerCapture(id))canvas.releasePointerCapture(id);if(active?.points.length){state.strokes.push(active);history.push({kind:'stroke',stroke:active});redo=[]}active=null;changed()}
function setPattern(id){finish();state={version:1,pattern:id,background:backgroundColor(state),strokes:[]};history=[];redo=[];$('#outline').innerHTML=svgMarkup(id);const p=patterns.find(p=>p.id===id);$('#picture-title').textContent=p.icon+' '+p.name;document.querySelectorAll('.pattern').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));changed()}
function ask(title,message,fn){finish();confirmAction=fn;$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-dialog').showModal()}
for(const [hex,name]of palette){const b=document.createElement('button');b.className='color';b.style.background=hex;b.setAttribute('aria-label',name);b.setAttribute('aria-pressed',String(hex===color));b.dataset.color=hex;b.onclick=()=>{finish();color=hex;rainbow=false;syncColor(name);$('#color-dialog').close()};$('#colors').append(b)}
function syncBrush(){updateBrushSummary($('#brush-summary'),$('#brush-icon'),$('#brush-name'),tool,stampShape)}
syncBrush();
for(const [id,icon,name]of brushes){const b=document.createElement('button');b.className='tool';b.innerHTML=`<span class="tool-icon">${icon}</span><span>${name}</span>`;b.setAttribute('aria-label',name);b.setAttribute('aria-pressed',String(id===tool));b.onclick=()=>{finish();tool=id;$('#stamp-options').hidden=id!=='stamp';syncBrush();$('#brush-picker').open=false;document.querySelectorAll('.tool').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))};$('#tools').append(b)}
for(const [id,icon,name] of stamps){const b=document.createElement('button');b.className='stamp-choice';b.textContent=icon;b.setAttribute('aria-label',name+'印章');b.setAttribute('aria-pressed',String(id===stampShape));b.onclick=()=>{finish();stampShape=id;syncBrush();document.querySelectorAll('.stamp-choice').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))};$('#stamp-options').append(b)}
for(const [n,label,px]of [[9,'細筆',5],[20,'中筆',10],[38,'粗筆',17]]){const b=document.createElement('button');b.className='size';b.innerHTML=`<span style="width:${px}px;height:${px}px"></span>`;b.setAttribute('aria-label',label);b.setAttribute('aria-pressed',String(n===size));b.onclick=()=>{finish();size=n;document.querySelectorAll('.size').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))};$('#sizes').append(b)}
let patternCategory='all';
function filterPatterns(){document.querySelectorAll('.pattern').forEach(b=>{b.hidden=patternCategory!=='all'&&b.dataset.category!==patternCategory});document.querySelectorAll('.category-choice').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===patternCategory)));requestAnimationFrame(fit)}
for(const c of [{id:'all',name:'全部',icon:'✨'},...patternCategories]){const b=document.createElement('button');b.className='category-choice';b.dataset.id=c.id;b.textContent=c.icon+' '+c.name;b.setAttribute('aria-label',c.name+'圖案');b.setAttribute('aria-pressed',String(c.id==='all'));b.onclick=()=>{finish();patternCategory=c.id;filterPatterns()};$('#pattern-categories').append(b)}
for(const p of patterns){const b=document.createElement('button');b.className='pattern';b.dataset.id=p.id;b.dataset.category=p.category;b.setAttribute('aria-pressed',String(p.id===state.pattern));b.innerHTML=(p.id==='blank'?'<span class="blank-icon">✨</span>':svgMarkup(p.id))+`<span>${p.name}</span>`;b.onclick=()=>{if(p.id===state.pattern)return;if(state.strokes.length||active)ask('換一張圖案嗎？','這張畫會被換掉。喜歡的作品，先請大人幫忙存成圖片。',()=>setPattern(p.id));else setPattern(p.id)};$('#patterns').append(b)}
canvas.addEventListener('pointerdown',e=>{if(pointer!==null||!e.isPrimary||(e.pointerType==='mouse'&&e.button!==0))return;if(state.strokes.length>=MAX_STROKES||state.strokes.reduce((n,s)=>n+s.points.length,0)>=MAX_POINTS-15000){$('#save-status').textContent='這張畫很豐富了！請大人儲存，再開新畫。';return}e.preventDefault();pointer=e.pointerId;canvas.setPointerCapture(pointer);active={tool,color,rainbow:tool!=='eraser'&&rainbow,size,stamp:stampShape,seed:crypto.getRandomValues(new Uint32Array(1))[0],points:[coordinate(e.clientX,e.clientY,canvas.getBoundingClientRect())]};schedule()});
canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer||!active)return;e.preventDefault();const rect=canvas.getBoundingClientRect();const events=e.getCoalescedEvents?.();for(const ev of events?.length?events:[e]){const p=coordinate(ev.clientX,ev.clientY,rect),last=active.points.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)>1.3&&active.points.length<14999)active.points.push(p)}schedule()});
for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{if(e.pointerId===pointer)finish()});
window.addEventListener('blur',finish);window.addEventListener('pagehide',()=>{finish();save()});document.addEventListener('visibilitychange',()=>{if(document.hidden){finish();save()}});window.addEventListener('resize',finish);
$('#undo').onclick=()=>{finish();const a=history.pop();if(a){if(a.kind==='stroke')state.strokes.pop();else state.background=a.before;redo.push(a)}syncBackground();changed()};$('#redo').onclick=()=>{finish();const a=redo.pop();if(a){if(a.kind==='stroke')state.strokes.push(a.stroke);else state.background=a.after;history.push(a)}syncBackground();changed()};
$('#parent').onclick=()=>{finish();$('#parent-dialog').showModal()};$('[data-close]').onclick=()=>$('#parent-dialog').close();$('#cancel').onclick=()=>{$('#confirm-dialog').close();confirmAction=null};$('#confirm').onclick=()=>{const action=confirmAction;confirmAction=null;$('#confirm-dialog').close();action?.()};$('#confirm-dialog').addEventListener('cancel',()=>confirmAction=null);
$('#clear').onclick=()=>{$('#parent-dialog').close();ask('換一張乾淨的紙嗎？','現在的顏色會清掉，圖案保留。請先儲存想留下的作品。',()=>setPattern(state.pattern))};
$('#export').onclick=async()=>{finish();const b=$('#export');b.disabled=true;b.textContent='正在準備圖片…';try{const output=document.createElement('canvas');output.width=W;output.height=H;const c=output.getContext('2d');c.fillStyle=backgroundColor(state);c.fillRect(0,0,W,H);c.drawImage(canvas,0,0);const svg=new Blob([svgMarkup(state.pattern)],{type:'image/svg+xml'}),url=URL.createObjectURL(svg),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});c.drawImage(img,0,0,W,H)}finally{URL.revokeObjectURL(url)}const blob=await new Promise(resolve=>output.toBlob(resolve,'image/png'));if(!blob)throw Error();if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(blob);$('#export-preview').replaceChildren();const preview=document.createElement('img');preview.src=exportUrl;preview.alt='完成的畫作，可長按儲存';const a=document.createElement('a');a.href=exportUrl;a.download='我的小小畫作.png';a.textContent='下載圖片（或長按上圖儲存）';$('#export-preview').append(preview,a);a.click();}catch{$('#export-preview').textContent='圖片暫時無法產生，請再試一次。作品仍在畫布上。'}finally{b.disabled=false;b.textContent='↓ 儲存作品 PNG'}};
$('#outline').innerHTML=svgMarkup(state.pattern);const p=patterns.find(p=>p.id===state.pattern);$('#picture-title').textContent=p.icon+' '+p.name;render();if(restoreMessage)$('#save-status').textContent=restoreMessage;

// Resize only the presentation; vector coordinates and the stored document stay intact.
const app=$('.app'),board=$('#board'),paper=$('.paper-frame');
function fit(){const r=paper.getBoundingClientRect();const f=fitBoard(Math.max(1,r.width-8),Math.max(1,r.height-8));board.style.width=f.width+'px';board.style.height=f.height+'px'}
const focusMode=createFocusMode({root:document.documentElement,doc:document,onChange:({focused,tools,native})=>{finish();document.body.classList.toggle('focus-mode',focused);document.body.classList.toggle('show-focus-tools',focused&&tools);$('.focus-controls').hidden=!focused;$('#focus-label').textContent=native?'全螢幕畫畫':'大畫布模式';$('#focus-tools').textContent=tools?'🎨 收起工具':'🎨 顯示工具';$('#focus-tools').setAttribute('aria-expanded',String(tools));requestAnimationFrame(fit)}});
$('#focus-enter').onclick=()=>focusMode.enter();$('#focus-exit').onclick=()=>focusMode.exit();$('#focus-tools').onclick=()=>focusMode.toggleTools();$('#focus-undo').onclick=()=>$('#undo').click();
for(const event of ['fullscreenchange','webkitfullscreenchange'])document.addEventListener(event,()=>focusMode.change());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&focusMode.getState().focused&&!document.querySelector('dialog[open]'))focusMode.exit()});
$('#brush-picker').addEventListener('toggle',()=>{finish();requestAnimationFrame(fit)});
$('#pattern-picker').addEventListener('toggle',()=>{finish();requestAnimationFrame(fit)});
if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>{finish();fit()}).observe(paper);
window.addEventListener('resize',fit);window.visualViewport?.addEventListener('resize',fit);requestAnimationFrame(fit);

const backgrounds=[['#ffffff','白色'],['#fff4d6','奶油黃'],['#fce6ed','淺粉紅'],['#e5f2fc','天空藍'],['#e7f3df','嫩綠'],['#eee7fa','淡紫']];
function syncBackground(){document.querySelectorAll('.background-choice').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===backgroundColor(state))));$('#background-open').style.background=backgroundColor(state)}
for(const [hex,name]of backgrounds){const b=document.createElement('button');b.className='background-choice';b.dataset.color=hex;b.style.background=hex;b.textContent=name;b.setAttribute('aria-label',name+'畫紙');b.onclick=()=>{finish();const before=backgroundColor(state);if(before!==hex){state.background=hex;history.push({kind:'background',before,after:hex});redo=[];changed()}syncBackground();$('#background-dialog').close()};$('#background-colors').append(b)}
syncBackground();$('#background-open').onclick=()=>{finish();syncBackground();$('#background-dialog').showModal()};$('#background-close').onclick=()=>$('#background-dialog').close();

function syncColor(name){$('#current-color').style.background=rainbow?'linear-gradient(120deg,#ef476f,#ffd166,#06d6a0,#118ab2,#9b5de5)':color;$('#color-name').textContent=rainbow?'彩虹筆色':name||palette.find(p=>p[0]===color)?.[1]||'我的顏色';$('#color-open').setAttribute('aria-label','目前筆色：'+$('#color-name').textContent+'，點一下選顏色');document.querySelectorAll('.color').forEach(b=>b.setAttribute('aria-pressed',String(!rainbow&&b.dataset.color===color)));$('#rainbow-color').setAttribute('aria-pressed',String(rainbow));$('#custom-color').value=color}
$('#color-open').onclick=()=>{finish();$('#color-dialog').showModal()};$('#color-close').onclick=()=>$('#color-dialog').close();
$('#custom-color').addEventListener('input',e=>{const value=e.target.value;if(!/^#[0-9a-f]{6}$/i.test(value))return;finish();color=value.toLowerCase();rainbow=false;syncColor('我的顏色')});
$('#rainbow-color').onclick=()=>{finish();rainbow=true;syncColor();$('#color-dialog').close()};syncColor();
